INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('99ec6d50-4d70-4e62-9da8-e7ddcc40d68d', '0b8ddab7-b106-4873-bc4d-3987421d265d', 3, 'As Pequenas Mortes', NULL, '{"intro": "Pequenos sacrif\u00edcios fortalecem a alma contra grandes quedas.", "prayer": "Ofere\u00e7a essa pequena morte pela convers\u00e3o de algu\u00e9m.", "practice": "Renuncie a uma pequena satisfa\u00e7\u00e3o hoje (um caf\u00e9, um doce, um coment\u00e1rio).", "reflection": "Cada ren\u00fancia \u00e9 um espa\u00e7o que se abre para a vida.", "journal_prompt": "O que voc\u00ea pode soltar para ser mais livre?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;